pageStyle:
div.author {
    width: 100%;
    font-family: serif;
}
div.author img {
    width: 300px;
    float: left;
    margin-right: 25px;
}

div.author span.name {
    display: block;
    font-size: 25px;
    font-weight: 700;
}

div.author span.position {
    display: block;
    font-size: 16px;
    font-weight: 700;
}

div.author span.description {
    display: block;
    font-size: 16px;
    font-weight: 500;
    margin-top: 25px;
}
